{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "In fed subjects, lefamulin had an oral bioavailability of 19%, below the 20% threshold, providing the only affirmative below-threshold human measurement among the retrieved evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Palmitic acid, a long-chain carboxylic acid, had 28% oral bioavailability in humans, above the threshold; however, it lacks the bicyclic prostaglandin-like core and extensive first-pass metabolism of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ursodeoxycholic acid had 50% systemic availability in healthy subjects, but its steroid scaffold is not representative of the query's prostaglandin-like metabolic liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Eplerenone had ~98% oral bioavailability in humans, but it is a metabolically stable steroid-like lactone, unlike the query's bicyclic ketone/tertiary alcohol system.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lefamulin had 25.8% absolute oral bioavailability in fasted healthy subjects, above threshold, but its structure and clearance mechanisms differ from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a prostaglandin-like bicyclic fatty acid (lubiprostone-type) with a cyclopentanone and tertiary alcohol; such structures undergo rapid first-pass metabolism in the GI tract and liver, resulting in very low systemic bioavailability. The retrieved high-F analogues lack this metabolic liability and are not transferable despite high assay-transfer scores. The only affirmative below-threshold human value (lefamulin fed 19%) and the known metabolic instability of the scaffold support a low F (<20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule.",
    "No retrieved analogue shares the prostaglandin-like bicyclic scaffold, cyclopentanone, tertiary alcohol, or gem-difluoropentyl side chain.",
    "High assay-transfer scores reflect general lipophilic carboxylic acid features rather than the query-specific first-pass metabolic liability.",
    "The only below-threshold human value (lefamulin fed 19%) is from a structurally unrelated antibiotic."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

